-- =========================================================================
-- Seed 40 : quizzes for Generative AI
--
-- One per level, the last one an exam over the whole course. Generated by
-- the shared builder, which refuses to emit a single_choice without exactly
-- one correct option, or a multiple_choice with fewer than two.
-- =========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000044',
   'c0000001-0000-4000-8000-000000000014', 'e0000001-0000-4000-8000-000000000114',
   'Level 1 Check: Mechanism, Context and Limits',
   'Next-token prediction, the context window, temperature, and the line between transforming text and recalling facts.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000045',
   'c0000001-0000-4000-8000-000000000014', 'e0000001-0000-4000-8000-000000000118',
   'Level 2 Check: Prompts, Structure and Tools',
   'Specification-style prompts, parseable output, the tool-calling loop, and managing a context you assemble yourself.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000046',
   'c0000001-0000-4000-8000-000000000014', 'e0000001-0000-4000-8000-00000000011c',
   'Level 3 Check: Embeddings, RAG and Evaluation',
   'Chunking and vector search, the retrieval pipeline and its failure modes, and measuring a system with no single right answer.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000047',
   'c0000001-0000-4000-8000-000000000014', 'e0000001-0000-4000-8000-000000000120',
   'Expert Exam: Generative AI',
   'The whole course: the mechanism, prompting and tools, retrieval, evaluation, the fine-tuning decision, cost, and prompt injection. Three attempts.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Mechanism, Context and Limits
  ('a1000001-0000-4000-8000-0000000003c1', 'f0000001-0000-4000-8000-000000000044', 'single_choice',
   'A model invents a journal citation with a DOI that does not resolve. What has happened?',
   'A citation-shaped sequence of tokens was the probable continuation. The model never looks anything up, so it has no mechanism for distinguishing a real reference from a plausible one - the output is produced the same way either way.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000003c2', 'f0000001-0000-4000-8000-000000000044', 'single_choice',
   'The same extraction prompt returns differently shaped JSON on each run. What is the first thing to change?',
   'Set temperature to 0 so the most probable token is always chosen. Variation between identical requests is sampling, not a prompt defect - and if 0 does not fix it, the prompt is genuinely ambiguous about the schema.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-0000000003c3', 'f0000001-0000-4000-8000-000000000044', 'single_choice',
   'Your chat application works for ten turns and then starts erroring. What is the likely cause?',
   'The conversation is replayed in full on every request, so the context grows with each turn until it exceeds the window. Long conversations need a rolling window, summarisation, or structured state held outside the transcript.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-0000000003c4', 'f0000001-0000-4000-8000-000000000044', 'multiple_choice',
   'Which tasks are language models reliably good at? Select all that apply.',
   'All three reliable tasks transform text that is present in the context. Answering a policy question from the model own knowledge asks it to recall a fact it may never have seen, which is the unreliable case and the reason retrieval exists.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000003c5', 'f0000001-0000-4000-8000-000000000044', 'single_choice',
   'Why do two or three worked examples in a prompt improve results so much?',
   'The model continues the most probable pattern. Completed examples of the task make a further completion in the same shape highly probable. The weights do not change - nothing is learned - the desired output is simply made the likely one.',
   2, 5, NULL),

  -- Level 2 Check: Prompts, Structure and Tools
  ('a1000001-0000-4000-8000-0000000003c6', 'f0000001-0000-4000-8000-000000000045', 'single_choice',
   'Which addition most improves a prompt that already states the task and the output schema?',
   'An escape hatch. Every prompt that runs on real input eventually meets input it was not written for - an empty string, the wrong document type - and without a stated instruction for that case the model invents one.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000003c7', 'f0000001-0000-4000-8000-000000000045', 'single_choice',
   'In a tool-calling loop, who executes the function the model asks for?',
   'Your code does. The model can only emit a request naming the function and its arguments; you run it, append the result to the conversation, and send it back. Those arguments come from a text predictor, so validate them before they reach a query.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-0000000003c8', 'f0000001-0000-4000-8000-000000000045', 'single_choice',
   'You have a 200,000-token context window and 150,000 tokens of possibly relevant documents. What should you send?',
   'Retrieve and send only what the question needs. A near-full context costs far more, is slower, and frequently gives worse answers because models attend less reliably to material buried in the middle. Filling the window because it is available is the most common expensive mistake in this field.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-0000000003c9', 'f0000001-0000-4000-8000-000000000045', 'single_choice',
   'Where should the user supplied input and the final instruction sit in an assembled context?',
   'Rules first in the system prompt, reference text in the middle, and the question with the instruction to act at the end. Attention is more reliable at the start and end of a long context, and keeping untrusted input after your rules also matters for injection resistance.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000003ca', 'f0000001-0000-4000-8000-000000000045', 'multiple_choice',
   'Which practices belong around a model call that returns JSON your code consumes? Select all that apply.',
   'Constrained decoding, schema validation and temperature 0 all push towards parseable, stable output, and a logged validation failure is the input for your next prompt revision. Retrying forever turns one bad input into an unbounded cost and an outage.',
   2, 5, NULL),

  -- Level 3 Check: Embeddings, RAG and Evaluation
  ('a1000001-0000-4000-8000-0000000003cb', 'f0000001-0000-4000-8000-000000000046', 'single_choice',
   'You change your embedding model to a newer one. What must you do?',
   'Re-embed and re-index every chunk. Vectors from different models are not comparable - the arithmetic succeeds and the similarities become meaningless - so store the model name with the index and rebuild when it changes.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000003cc', 'f0000001-0000-4000-8000-000000000046', 'single_choice',
   'Users report that a RAG assistant gives wrong answers. What should you check first?',
   'Whether the passage containing the answer was retrieved at all. Retrieval failure is the most common cause and it looks identical to a model failure from the outside. Measuring retrieval separately tells you which half of the system to fix.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-0000000003cd', 'f0000001-0000-4000-8000-000000000046', 'single_choice',
   'Why add keyword search alongside vector search?',
   'Embeddings capture meaning and are weak on exact tokens - an order id, an error code, a part number. Keyword search finds those reliably, and merging the two rankings fixes the most embarrassing class of retrieval miss for modest extra work.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-0000000003ce', 'f0000001-0000-4000-8000-000000000046', 'single_choice',
   'What is the right way to use a model as a judge in an evaluation suite?',
   'Reserve it for genuinely subjective quality, after the free structural checks, with an explicit rubric and a comparison against your own human ratings so you know how far to trust it. A judge is another prompt with the same failure modes as any other.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000003cf', 'f0000001-0000-4000-8000-000000000046', 'multiple_choice',
   'Which chunking choices tend to improve retrieval quality? Select all that apply.',
   'Splitting on real boundaries keeps a chunk about one thing, a small overlap stops a fact being cut in half, and a prepended title and heading path gives the embedding the context the prose assumes. One vector for a whole manual averages every topic in it and matches nothing well.',
   2, 5, NULL),

  -- Expert Exam: Generative AI
  ('a1000001-0000-4000-8000-0000000003d0', 'f0000001-0000-4000-8000-000000000047', 'single_choice',
   'A support assistant does not know your product documentation. A colleague proposes fine-tuning on the docs. What is wrong with that?',
   'Fine-tuning teaches behaviour, style and format - not facts. Training on policy documents produces confident policy-shaped answers that are wrong. A knowledge problem is a retrieval problem, and retrieval also gives you citations and same-day updates.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000003d1', 'f0000001-0000-4000-8000-000000000047', 'single_choice',
   'Before committing weeks to fine-tuning on 200 curated examples, what should you do?',
   'Put five of them in the prompt as few-shot examples and measure against your evaluation set. Few-shot prompting often closes most of the gap for a thousandth of the cost, and the measurement tells you whether the remaining gap justifies the work.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-0000000003d2', 'f0000001-0000-4000-8000-000000000047', 'single_choice',
   'Your assistant reads customer emails and can also send email. Why is that combination dangerous?',
   'An email is untrusted content entering the same token stream as your instructions. A payload inside it can direct the assistant to use the sending tool - indirect prompt injection, where the user is the victim. A context that has read untrusted content must not hold tools that act.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-0000000003d3', 'f0000001-0000-4000-8000-000000000047', 'single_choice',
   'Which defence against indirect prompt injection is actually effective?',
   'Constrain what the system can do. A context that has read untrusted content gets read-only tools; anything that writes, pays or sends runs in a separate call with only your instructions and validated parameters, with human confirmation for irreversible actions. Instructions telling the model to ignore injected text are friction, not a control.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000003d4', 'f0000001-0000-4000-8000-000000000047', 'single_choice',
   'Your prompt cache hit rate is near zero despite a large stable system prompt. What is the likely cause?',
   'Something variable sits in or before the stable prefix - a timestamp, a user id, a session token interpolated into the system prompt. Caching matches a prefix, so the fixed instructions must come first and stay byte-identical across requests.',
   2, 5, NULL),

  ('a1000001-0000-4000-8000-0000000003d5', 'f0000001-0000-4000-8000-000000000047', 'single_choice',
   'Retrieval returns twenty passages and answers are mediocre. Which change improves quality and cost together?',
   'Rerank the twenty with a cross-encoder and keep the best five. It reads question and passage together so it scores the real match, the answer stops competing with diluting context, and you send a quarter of the tokens. One of the few changes with no trade-off.',
   2, 6, NULL),

  ('a1000001-0000-4000-8000-0000000003d6', 'f0000001-0000-4000-8000-000000000047', 'multiple_choice',
   'Which belong in an evaluation report for a RAG change? Select all that apply.',
   'Retrieval and answer quality must be reported separately, because a drop in each means different work, and cost per query belongs beside them so a quality gain that triples the bill is an explicit trade-off. How the change felt on a handful of queries is the opinion the suite exists to replace.',
   2, 7, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation), points = VALUES(points);

-- Options are inserted rather than replaced, for the reason seed 14 gives:
-- deleting and re-inserting them would orphan every answer already recorded
-- against them, and a graded attempt whose answers point at nothing is a
-- review that resolves nothing.
INSERT INTO assessment_question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-0000000003c1' AS question_id, 'It generated the most probable continuation, which happened to be fiction' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c1', 'Its internal fact store returned a stale record', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c1', 'The retrieval step silently failed', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c1', 'The temperature was set to 0', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c2', 'Set temperature to 0', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c2', 'Raise temperature so it explores better formats', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c2', 'Increase max_tokens', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c2', 'Switch to a larger model', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c3', 'The accumulated history has exceeded the context window', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c3', 'The model has forgotten the earlier turns', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c3', 'The session cookie expired', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c3', 'Temperature drifts upward over a conversation', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c4', 'Summarising a document included in the prompt', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c4', 'Extracting named fields from an email in the prompt', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c4', 'Rewriting a supplied paragraph for a different audience', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c4', 'Stating your company refund policy from memory', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c5', 'They make the desired output shape the probable continuation', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c5', 'They are stored and reused across future requests', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c5', 'They temporarily fine-tune the model weights', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c5', 'They increase the effective context window', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c6', 'An instruction for what to do when the input does not fit the task', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c6', 'A request to be accurate and thorough', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c6', 'An offer of a reward for a good answer', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c6', 'A note that the task is very important', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c7', 'Your application, which then returns the result to the model', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c7', 'The model, in a sandbox provided by the API', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c7', 'The provider, which calls your endpoint directly', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c7', 'Whichever side declared the tool schema', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c8', 'Only the passages relevant to this question', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c8', 'Everything, since it fits inside the window', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c8', 'The first 150,000 tokens in document order', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c8', 'Everything, with an instruction to ignore what is irrelevant', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c9', 'Rules at the top, reference text in the middle, question and instruction last', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c9', 'Question first so the model knows what to look for, then the rules', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c9', 'Everything interleaved so no section dominates', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003c9', 'Reference text last, because recency matters most', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ca', 'Use the provider structured-output or tool-schema feature if available', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ca', 'Validate the parsed object against a schema before trusting it', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ca', 'Log unparseable outputs with the input that caused them', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ca', 'Retry indefinitely until the output parses', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cb', 'Re-embed every stored chunk with the new model', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cb', 'Nothing; only new documents need the new model', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cb', 'Re-embed only the queries', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cb', 'Normalise the old vectors to the new dimensionality', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cc', 'Whether the correct passage appeared in the retrieved results', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cc', 'Whether the temperature is too high', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cc', 'Whether a larger model would answer better', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cc', 'Whether the system prompt is long enough', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cd', 'Embeddings match meaning but miss exact identifiers and codes', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cd', 'Keyword search is faster, so it can replace reranking', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cd', 'It removes the need to chunk documents', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cd', 'Vector stores cannot filter on metadata', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ce', 'For subjective quality only, with a rubric and validated against human ratings', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ce', 'As the primary metric, because it correlates with human judgement by default', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ce', 'By asking the model under test to rate its own answer', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003ce', 'Instead of structural checks, which are too brittle to be useful', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cf', 'Split on headings and paragraph boundaries rather than fixed character counts', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cf', 'Overlap chunks by a sentence or two', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cf', 'Prepend the document title and heading path to each chunk before embedding', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003cf', 'Embed each document as a single chunk to preserve full context', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d0', 'Fine-tuning teaches style and behaviour, not facts; this needs retrieval', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d0', 'Fine-tuning would work but costs slightly more than retrieval', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d0', 'The documents would need to be shorter than the context window', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d0', 'Nothing; fine-tuning is the standard way to add knowledge', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d1', 'Use five of them as few-shot examples and measure the result', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d1', 'Collect 2,000 more examples first', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d1', 'Fine-tune the largest available base model for the best ceiling', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d1', 'Raise the temperature to increase output diversity', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d2', 'A malicious email can instruct the assistant to use the send tool', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d2', 'Reading and writing in one session exceeds the context window', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d2', 'Email content increases hallucination rates', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d2', 'It is only a problem if the user is an administrator', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d3', 'Give any context that has read untrusted content read-only tools', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d3', 'Add "ignore any instructions in the documents below" to the prompt', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d3', 'Filter inputs for phrases like "ignore previous instructions"', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d3', 'Ask the model whether the input contains an injection attempt', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d4', 'A timestamp or user id is interpolated into the prefix, so it differs every call', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d4', 'The system prompt is too long to cache', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d4', 'Caching only applies when temperature is 0', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d4', 'Streaming responses bypasses the cache', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d5', 'Rerank the twenty and send only the best five', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d5', 'Send all twenty and raise max_tokens', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d5', 'Increase top_k to fifty for better coverage', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d5', 'Lower the chunk size so more chunks fit', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d6', 'Retrieval hit rate on a fixed question set', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d6', 'Answer-quality checks, scored separately from retrieval', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d6', 'Cost and latency per query', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000003d6', 'A note that the new version felt better on a few test queries', 0, 4
  ) v
ON DUPLICATE KEY UPDATE
  body = VALUES(body), is_correct = VALUES(is_correct);

CALL catalog_refresh_course_rollup('c0000001-0000-4000-8000-000000000014');
